+func TestInitializeTableBillingMode(t *testing.T) {
+	for _, tt := range []struct {
+		name            string
+		configuredMode  string
+		existingMode    string
+		missing         bool
+		wantAutoScaling bool
+		wantCreated     bool
+		wantLog         string
